    function getDishSvgIcon(dishKey, sizeClass = "w-9 h-9") {
      if (dishKey === "metditu" && CASUAL_2D_ASSETS.st_met) {
        return `<img src="${CASUAL_2D_ASSETS.st_met}" alt="Mẹt Dì Tư" class="${sizeClass} rounded-xl object-cover border border-amber-400 shadow-sm shrink-0 bg-amber-50" />`;
      }
      const src = CASUAL_2D_ASSETS[dishKey] || CASUAL_2D_ASSETS.tron;
      return `<img src="${src}" class="${sizeClass} rounded-xl object-cover border border-amber-400 shadow-sm" alt="${escapeHtml(dishKey)}" />`;
    }

    function getIngredientSvgIcon(ingId, sizeClass = "w-9 h-9") {
      const src = CASUAL_2D_ASSETS["ing_" + ingId] || CASUAL_2D_ASSETS.ing_banhtrang;
      return `<img src="${src}" class="${sizeClass} rounded-xl object-cover border border-amber-300 shadow-sm" alt="${escapeHtml(ingId)}" />`;
    }

    function getIngredientImgSrc(ingId) {
      return CASUAL_2D_ASSETS["ing_" + ingId] || CASUAL_2D_ASSETS.ing_banhtrang;
    }

    function spawnFlyingIngredientSprites(ingIds = ["banhtrang", "xoai"]) {
      const layer = document.getElementById("flying-ingredients-layer");
      const bowlWrap = document.getElementById("bowl-visual-wrapper");
      if (!layer) return;

      ingIds.forEach((id, idx) => {
        setTimeout(() => {
          const img = document.createElement("img");
          img.src = getIngredientImgSrc(id);
          img.className = "flying-ing-sprite object-cover";
          const startX = (idx % 2 === 0 ? -1 : 1) * (45 + Math.random() * 35);
          const startY = -50 - Math.random() * 25;
          img.style.setProperty("--start-x", `${Math.round(startX)}px`);
          img.style.setProperty("--start-y", `${Math.round(startY)}px`);
          layer.appendChild(img);
          setTimeout(() => img.remove(), 700);
        }, idx * 95);
      });

      if (bowlWrap) {
        bowlWrap.classList.remove("bowl-toss-anim");
        void bowlWrap.offsetWidth;
        bowlWrap.classList.add("bowl-toss-anim");
      }
    }

    function scrollDishRibbon(deltaX) {
      const ribbon = document.getElementById("sell-dish-grid");
      if (ribbon) ribbon.scrollBy({ left: deltaX, behavior: "smooth" });
    }

    function openQuickMenuModal() {
      playSFX("snip");
      document.getElementById("modal-quick-menu").classList.remove("hidden");
    }
    function closeQuickMenuModal() {
      document.getElementById("modal-quick-menu").classList.add("hidden");
    }

    function escapeHtml(str) {
      return String(str || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    }

    function renderAvatarContent(avatarVal, imgClass = "w-full h-full object-cover") {
      if (!avatarVal) {
        return `<img src="${CASUAL_2D_ASSETS.ditu_mascot}" alt="Avatar" class="${escapeHtml(imgClass)}" />`;
      }
      const preset = AVATAR_PRESETS.find(p => p.id === avatarVal);
      if (preset) {
        return `<img src="${preset.src}" alt="${escapeHtml(preset.label)}" class="${escapeHtml(imgClass)}" />`;
      }
      const isSafeDataImage = typeof avatarVal === "string" && /^data:image\/(png|jpeg|jpg|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(avatarVal.trim());
      if (isSafeDataImage) {
        return `<img src="${avatarVal.trim()}" alt="Avatar" class="${escapeHtml(imgClass)}" />`;
      }
      if (avatarVal === "👩‍🍳" || avatarVal === "👵") return `<img src="${CASUAL_2D_ASSETS.ditu_mascot}" alt="Dì Tư" class="${escapeHtml(imgClass)}" />`;
      if (avatarVal === "👧") return `<img src="${CASUAL_2D_ASSETS.av_chef_girl}" alt="Nữ" class="${escapeHtml(imgClass)}" />`;
      if (avatarVal === "🧑🍳" || avatarVal === "👨🍳" || avatarVal === "👦") return `<img src="${CASUAL_2D_ASSETS.av_chef_boy}" alt="Nam" class="${escapeHtml(imgClass)}" />`;
      if (avatarVal === "🦊" || avatarVal === "🐼") return `<img src="${CASUAL_2D_ASSETS.av_fox}" alt="Cáo" class="${escapeHtml(imgClass)}" />`;
      return `<span>${escapeHtml(avatarVal)}</span>`;
    }

    let pinAttemptTracker = { count: 0, lockUntil: 0 };

    function hashShopPin(shopKey, rawPin) {
      const str = `bt_v6_salt_${shopKey}_${String(rawPin).trim()}`;
      let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
      for (let i = 0; i < str.length; i++) {
        const ch = str.charCodeAt(i);
        h1 = Math.imul(h1 ^ ch, 2654435761);
        h2 = Math.imul(h2 ^ ch, 1597334677);
      }
      h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
      h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
      return "PINH_" + (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
    }

    function verifyShopPin(shopKey, inputPin, storedPin) {
      if (!storedPin) return false;
      const now = Date.now();
      if (pinAttemptTracker.lockUntil > now) {
        const waitSec = Math.ceil((pinAttemptTracker.lockUntil - now) / 1000);
        if (typeof showToast === "function") showToast(`⏳ Nhập sai nhiều lần! Vui lòng thử lại sau ${waitSec}s.`);
        return false;
      }
      const cleanInput = String(inputPin || "").trim();
      const hashedInput = hashShopPin(shopKey, cleanInput);
      const isValid = String(storedPin) === hashedInput || (!String(storedPin).startsWith("PINH_") && String(storedPin) === cleanInput);
      if (!isValid) {
        pinAttemptTracker.count += 1;
        if (pinAttemptTracker.count >= 5) {
          pinAttemptTracker.lockUntil = now + 30000;
          pinAttemptTracker.count = 0;
        }
      } else {
        pinAttemptTracker.count = 0;
        pinAttemptTracker.lockUntil = 0;
      }
      return isValid;
    }

    let avatarUploadTarget = "login";
    let profileTempAvatar = "av_ditu";

    function triggerAvatarUpload(target) {
      avatarUploadTarget = target;
      const input = document.getElementById("hidden-avatar-upload");
      if (input) { input.value = ""; input.click(); }
    }

    function handleAvatarFileSelected(event) {
      const file = event.target.files && event.target.files[0];
      if (!file || !file.type.startsWith("image/")) return;
      const reader = new FileReader();
      reader.onload = function(e) {
        const img = new Image();
        img.onload = function() {
          const canvas = document.createElement("canvas");
          const size = 128; canvas.width = size; canvas.height = size;
          const ctx = canvas.getContext("2d");
          const minSide = Math.min(img.width, img.height);
          ctx.drawImage(img, (img.width - minSide)/2, (img.height - minSide)/2, minSide, minSide, 0, 0, size, size);
          const dataUrl = canvas.toDataURL("image/jpeg", 0.82);
          try { localStorage.setItem("btt_local_custom_avatar_v15", dataUrl); } catch (err) {}
          state.localCustomAvatar = dataUrl;
          if (avatarUploadTarget === "login") {
            loginSelectedAvatar = dataUrl;
            userManuallyChangedLoginAvatar = true;
            renderLoginAvatarGrid();
          } else {
            profileTempAvatar = dataUrl;
            renderProfileAvatarGrid();
          }
          playSFX("cash"); showToast("📷 Đã lưu ảnh đại diện trên thiết bị (Bảo mật riêng tư NĐ 147)!");
        };
        img.src = e.target.result;
      };
      reader.readAsDataURL(file);
    }


